namespace LogistixServer.Domain.Model.Domain.Base
{
    /// <summary>
    /// Represents a dispatch job with its details, status, schedule, and assignments.
    /// </summary>
    public sealed class Dispatch : BaseModel
    {
        /// <summary> Unique identifier for the dispatch job. </summary>
        public Guid DispatchId { get; }

        /// <summary> Identifier of the associated job. </summary>
        public Guid JobId { get; }

        /// <summary> Account this dispatch belongs to. </summary>
        public Guid AccountId { get; }

        /// <summary> Details of the dispatch: routes, assignments, etc. </summary>
        public DispatchDetails Details { get; }

        /// <summary> Current status of the dispatch. </summary>
        public DispatchStatus Status { get; private set; }

        /// <summary> Expected departure time. </summary>
        public DateTimeOffset ExpectedDeparture { get; }

        /// <summary> Expected arrival time, if scheduled. </summary>
        public DateTimeOffset? ExpectedArrival { get; }

        /// <summary> Driver assigned to the dispatch. </summary>
        public Guid? DriverId { get; private set; }

        /// <summary> Vehicle assigned to the dispatch. </summary>
        public Guid? VehicleId { get; private set; }

        /// <summary> Last updated timestamp. </summary>
        public DateTimeOffset LastUpdated { get; private set; }

        public Dispatch(
            Guid dispatchId,
            Guid jobId,
            Guid accountId,
            DispatchDetails details,
            DispatchStatus initialStatus,
            DateTimeOffset expectedDeparture,
            DateTimeOffset? expectedArrival = null,
            Guid? driverId = null,
            Guid? vehicleId = null)
        {
            DispatchId        = dispatchId;
            JobId             = jobId;
            AccountId         = accountId;
            Details           = details ?? throw new ArgumentNullException(nameof(details));
            Status            = initialStatus;
            ExpectedDeparture = expectedDeparture;
            ExpectedArrival   = expectedArrival;
            DriverId          = driverId;
            VehicleId         = vehicleId;
            LastUpdated       = DateTimeOffset.UtcNow;
        }

        /// <summary> Updates the dispatch status. </summary>
        public void UpdateStatus(DispatchStatus newStatus)
        {
            Status = newStatus;
            LastUpdated = DateTimeOffset.UtcNow;
        }

        /// <summary> Assigns a driver. </summary>
        public void AssignDriver(Guid driverId)
        {
            DriverId = driverId;
            LastUpdated = DateTimeOffset.UtcNow;
        }

        /// <summary> Assigns a vehicle. </summary>
        public void AssignVehicle(Guid vehicleId)
        {
            VehicleId = vehicleId;
            LastUpdated = DateTimeOffset.UtcNow;
        }

        /// <summary> Reschedules expected times. </summary>
        public void Reschedule(DateTimeOffset newDeparture, DateTimeOffset? newArrival = null)
        {
            if (newDeparture == default) throw new ArgumentException("Invalid departure time.", nameof(newDeparture));
            ExpectedDeparture = newDeparture;
            ExpectedArrival = newArrival;
            LastUpdated = DateTimeOffset.UtcNow;
        }
    }

    /// <summary>
    /// Detailed dispatch information (e.g., list of routes, tasks).
    /// </summary>
    public sealed class DispatchDetails
    {
        public List<Route> Routes { get; }
        public List<TaskAssignment> Assignments { get; }

        public DispatchDetails(IEnumerable<Route> routes, IEnumerable<TaskAssignment> assignments)
        {
            Routes = new List<Route>(routes);
            Assignments = new List<TaskAssignment>(assignments);
        }
    }

    public sealed class Route
    {
        public Guid RouteId { get; }
        public string Description { get; }
        // other route-specific properties

        public Route(Guid routeId, string description)
        {
            RouteId = routeId;
            Description = description ?? throw new ArgumentNullException(nameof(description));
        }
    }

    public sealed class TaskAssignment
    {
        public Guid AssignmentId { get; }
        public string TaskDescription { get; }
        // other assignment-specific properties

        public TaskAssignment(Guid assignmentId, string taskDescription)
        {
            AssignmentId = assignmentId;
            TaskDescription = taskDescription ?? throw new ArgumentNullException(nameof(taskDescription));
        }
    }

    public enum DispatchStatus
    {
        Pending,
        InProgress,
        Completed,
        Cancelled
    }
}"}

