    public sealed class BillingPayment : BaseModel
    {
        /// <summary> Unique identifier for the billing record. </summary>
        public Guid BillingId { get; }

        /// <summary> Reference to the associated invoice. </summary>
        public Guid InvoiceId { get; }

        /// <summary> The account associated with this payment. </summary>
        public Guid AccountId { get; }

        /// <summary> The amount paid in this transaction. </summary>
        public decimal Amount { get; }

        /// <summary> The currency of the transaction (ISO 4217 code). </summary>
        public string Currency { get; }

        /// <summary> The date and time when the payment was processed. </summary>
        public DateTimeOffset PaymentDate { get; }

        /// <summary> Payment method used (e.g., CreditCard, ACH, WireTransfer). </summary>
        public PaymentMethod Method { get; }

        /// <summary> Reference ID from the payment processor (e.g., transaction ID). </summary>
        public string? TransactionReference { get; private set; }

        /// <summary> Current status of the payment. </summary>
        public PaymentStatus Status { get; private set; }

        private readonly Dictionary<string, string> _metadata;
        /// <summary> Additional metadata fields. </summary>
        public IReadOnlyDictionary<string, string> Metadata => _metadata;

        public BillingPayment(
            Guid billingId,
            Guid invoiceId,
            Guid accountId,
            decimal amount,
            string currency,
            DateTimeOffset? paymentDate,
            PaymentMethod method,
            PaymentStatus initialStatus = PaymentStatus.Pending,
            string? transactionReference = null,
            IDictionary<string, string>? metadata = null)
        {
            if (string.IsNullOrWhiteSpace(currency) || currency.Length != 3)
                throw new ArgumentException("Currency must be a 3-letter ISO code.", nameof(currency));

            BillingId            = billingId;
            InvoiceId            = invoiceId;
            AccountId            = accountId;
            Amount               = amount >= 0 ? amount : throw new ArgumentOutOfRangeException(nameof(amount));
            Currency             = currency;
            PaymentDate          = paymentDate ?? DateTimeOffset.UtcNow;
            Method               = method;
            Status               = initialStatus;
            TransactionReference = transactionReference;
            _metadata            = metadata != null
                                   ? new Dictionary<string, string>(metadata)
                                   : new Dictionary<string, string>();
        }

        /// <summary>
        /// Updates the transaction reference (e.g., processor ID).
        /// </summary>
        public void SetTransactionReference(string reference)
        {
            if (string.IsNullOrWhiteSpace(reference))
                throw new ArgumentException("Transaction reference cannot be empty.", nameof(reference));
            TransactionReference = reference;
        }

        /// <summary>
        /// Updates the payment status.
        /// </summary>
        public void UpdateStatus(PaymentStatus newStatus)
        {
            Status = newStatus;
        }

        /// <summary>
        /// Adds or updates a metadata key-value pair.
        /// </summary>
        public void AddOrUpdateMetadata(string key, string value)
        {
            if (string.IsNullOrWhiteSpace(key)) throw new ArgumentException("Metadata key is required.", nameof(key));
            _metadata[key] = value;
        }
    }

    /// <summary>
    /// Supported payment methods.
    /// </summary>
    public enum PaymentMethod
    {
        CreditCard,
        ACH,
        WireTransfer,
        Other
    }

