using System.Collections.Generic;

namespace LogistixServer.Domain.Model.Domain.Inventory
{
    /// <summary>
    /// Represents inventory associated with a job and account, including items and metadata.
    /// </summary>
    public sealed class Inventory : BaseModel
    {
        /// <summary> Identifier for the job this inventory belongs to. </summary>
        public Guid JobId { get; }

        /// <summary> Identifier for the account this inventory belongs to. </summary>
        public Guid AccountId { get; }

        private readonly List<InventoryItem> _items;
        /// <summary> Collection of inventory items. </summary>
        public IReadOnlyList<InventoryItem> Items => _items.AsReadOnly();

        private readonly Dictionary<string, string> _metadata;
        /// <summary> Additional metadata about the inventory. </summary>
        public IReadOnlyDictionary<string, string> Metadata => _metadata;

        /// <summary> When the inventory was last updated. </summary>
        public DateTimeOffset LastUpdated { get; private set; }

        public Inventory(
            Guid jobId,
            Guid accountId,
            IEnumerable<InventoryItem> items,
            IDictionary<string, string>? metadata = null)
        {
            JobId      = jobId;
            AccountId  = accountId;
            _items     = new List<InventoryItem>(items ?? Array.Empty<InventoryItem>());
            _metadata  = metadata != null
                         ? new Dictionary<string, string>(metadata)
                         : new Dictionary<string, string>();
            LastUpdated = DateTimeOffset.UtcNow;
        }

        /// <summary> Adds an inventory item if not already present. </summary>
        public void AddItem(InventoryItem item)
        {
            if (item == null) throw new ArgumentNullException(nameof(item));
            if (!_items.Contains(item)) _items.Add(item);
            LastUpdated = DateTimeOffset.UtcNow;
        }

        /// <summary> Removes an inventory item if present. </summary>
        public void RemoveItem(InventoryItem item)
        {
            _items.Remove(item);
            LastUpdated = DateTimeOffset.UtcNow;
        }

        /// <summary> Updates or adds a metadata key-value pair. </summary>
        public void UpdateMetadata(string key, string value)
        {
            if (string.IsNullOrWhiteSpace(key)) throw new ArgumentException("Key is required", nameof(key));
            _metadata[key] = value;
            LastUpdated = DateTimeOffset.UtcNow;
        }
    }

    /// <summary>
    /// Represents a single inventory item with quantity and details.
    /// </summary>
    public sealed class InventoryItem : IEquatable<InventoryItem>
    {
        public Guid ItemId { get; }
        public string Name { get; }
        public int Quantity { get; private set; }
        public string? Description { get; }

        public InventoryItem(Guid itemId, string name, int quantity, string? description = null)
        {
            if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException("Name is required", nameof(name));
            if (quantity < 0) throw new ArgumentOutOfRangeException(nameof(quantity));

            ItemId = itemId;
            Name = name;
            Quantity = quantity;
            Description = description;
        }

        /// <summary> Adjusts the quantity of the item. </summary>
        public void AdjustQuantity(int delta)
        {
            var newQty = Quantity + delta;
            if (newQty < 0) throw new InvalidOperationException("Quantity cannot be negative.");
            Quantity = newQty;
        }

        public bool Equals(InventoryItem? other)
            => other != null && ItemId == other.ItemId;

        public override bool Equals(object? obj) => Equals(obj as InventoryItem);
        public override int GetHashCode() => ItemId.GetHashCode();
    }
}"}

